// word-RAM digit select (read): lane l of the digit = bit (kk * W + l) of the word, for l < W (width W = 2**lw)
module sc_rdsel4 (input [31:0] w, input [4:0] kk, input [1:0] lw, output [3:0] d);
    reg o0; always @* begin o0 = 1'b0; case (lw) 2'd2: o0 = w[(kk << 2) + 0]; 2'd1: o0 = w[(kk << 1) + 0]; 2'd0: o0 = w[(kk << 0) + 0]; default: o0 = 1'b0; endcase end
    assign d[0] = o0;
    reg o1; always @* begin o1 = 1'b0; case (lw) 2'd2: o1 = w[(kk << 2) + 1]; 2'd1: o1 = w[(kk << 1) + 1]; default: o1 = 1'b0; endcase end
    assign d[1] = o1;
    reg o2; always @* begin o2 = 1'b0; case (lw) 2'd2: o2 = w[(kk << 2) + 2]; default: o2 = 1'b0; endcase end
    assign d[2] = o2;
    reg o3; always @* begin o3 = 1'b0; case (lw) 2'd2: o3 = w[(kk << 2) + 3]; default: o3 = 1'b0; endcase end
    assign d[3] = o3;
endmodule

// write accumulator + digit counter: digits are inserted at digit index kk; the last digit of a pass (32/W of them) gives flush = 1 and the whole word on `word`
