    assign word[27] = (en & (lw == 2'd2) ? (kk == 5'd6) : (lw == 2'd1) ? (kk == 5'd13) : (kk == 5'd27)) ? (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[27];
